pairs = [(3, 797), (13, 787), (31, 769), (43, 757), (61, 739), (67, 733), (73, 727), (109, 691), (127, 673), (139, 661), (157, 643), (181, 619), (193, 607), (199, 601), (223, 577), (229, 571), (277, 523), (313, 487), (337, 463), (367, 433), (379, 421)]

results = {}

for q, r in pairs:
    print(f"\n--- Analyzing (q, r) = ({q}, {r}) ---")

    # Calculate constants for P1 and P3
    C1 = q - r # q - (800 - q) = 2q - 800
    C3 = r - q # (800 - q) - q = 800 - 2q

    # List all primes p < q
    primes_p = [p for p in range(2, q) if is_prime(p)]

    found_p = []

